def divide(a: float, b: float) -> float:
    """Generated by adaptation: inverse of multiplication."""
    if b == 0:
        raise ValueError('Cannot divide by zero')
    result = 0.0
    abs_b = abs(b)
    temp = abs(a)
    while temp >= abs_b:
        temp -= abs_b
        result += 1
    if a * b < 0:
        result = -result
    return result + (temp / abs_b)

def test_divide():
    return divide(10, 2) == 5.0 and divide(7, 2) == 3.5 and abs(divide(1, 3) - 0.333) < 0.01
